'use strict';
const base = document.body.dataset.base;
const page = document.body.dataset.page;
const root = document.querySelector('#main');
let data;
let chartSequence=0;
const historyWindows=new Set();
let chartResizeTimer,chartViewportWidth=window.innerWidth;
window.addEventListener('resize',()=>{
 if(window.innerWidth===chartViewportWidth)return;
 chartViewportWidth=window.innerWidth;
 clearTimeout(chartResizeTimer);
 chartResizeTimer=setTimeout(()=>{
  if(!data)return;
  document.querySelectorAll('.chart-wrap[data-chart-type="line"]').forEach(wrap=>{
   const open=[...wrap.querySelectorAll('details[open]')].map(el=>el.className);
   const box=document.createElement('div');box.innerHTML=chart(wrap.dataset.metric,wrap.dataset.compact==='true');
   open.forEach(cls=>box.querySelector(`details.${cls}`)?.setAttribute('open',''));
   wrap.replaceWith(box.firstElementChild);
  });
 },120);
});
document.addEventListener('change',event=>{
 if(!event.target.matches('.history-window'))return;
 const wrap=event.target.closest('.chart-wrap'),id=wrap.dataset.metric;
 if(event.target.checked)historyWindows.add(id);else historyWindows.delete(id);
 wrap.outerHTML=chart(id,wrap.dataset.compact==='true');
 document.querySelector(`.chart-wrap[data-metric="${id}"] .history-window`)?.focus();
});
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl = value => { try { const u = new URL(value); return u.protocol === 'https:' ? esc(u.href) : '#'; } catch { return '#'; } };
const layerOf = id => data.layers.find(l => l.id === id);
const metricOf = id => data.metrics.find(m => m.id === id);
const sourceOf = id => data.sources.find(s => s.id === id);
const records = id => data.observations.filter(o => o.metric === id && !o.superseded_by).sort((a,b) => a.year-b.year || a.period.localeCompare(b.period));
const number = value => new Intl.NumberFormat('en-US',{maximumFractionDigits:3}).format(value);
const valueOf = o => `${({approx:'≈',gt:'>',lt:'<'}[o.precision] || '')}${number(o.value)}${o.upper != null ? `–${number(o.upper)}` : ''}`;
const statusLabel = s => ({observation:'Reported observation',estimate:'Historical estimate',forecast:'Forecast','government-target':'Government target','company-commitment':'Company commitment'}[s] || s);
const historicalStatus = s => ['observation','estimate'].includes(s);
const normalizeName = value => String(value||'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
const normalizeHost = value => { try { const h=new URL(value).hostname.toLowerCase(); return h.startsWith('www.')?h.slice(4):h; } catch { return ''; } };
// First-party test: source publisher matches (or is a "Company X" vs "Company X Platforms"-style
// prefix of) the company name, OR the source host is the company's own ir_url/blog_urls host.
const isFirstParty = (source,company) => {
 if(!company)return false;
 const pub=normalizeName(source.publisher), name=normalizeName(company.name);
 if(name && (pub===name || pub.startsWith(name+' ')))return true;
 const sourceHost=normalizeHost(source.url);
 if(!sourceHost)return false;
 return [company.ir_url,...(company.blog_urls||[])].some(url=>{const h=normalizeHost(url);return h && (sourceHost===h || sourceHost.endsWith('.'+h));});
};
// Reader-facing attribution, distinct from the raw status: a forecast is either the tracked
// company's own guidance or an independent/third-party projection; other statuses keep their label.
const attributionLabel = o => {
 const m=metricOf(o.metric), s=sourceOf(o.source);
 if(o.status==='forecast'){
  const company=m.company?companyOf(m.company):null;
  return isFirstParty(s,company)?'Company guidance':'Independent projection';
 }
 return {observation:'Reported observation',estimate:'Historical estimate','company-commitment':'Company commitment','government-target':'Government target'}[o.status] || statusLabel(o.status);
};
if(typeof module!=='undefined')module.exports={attributionLabel};
const dateLabel = d => d ? new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'}).format(new Date(d.length === 10 ? `${d}T12:00:00Z` : d)) : 'Publication date unlisted';
const vintageLabel = d => d ? dateLabel(d) : 'date unlisted';
// One source of truth for the schedule sentence on the methodology page: prefer a structured
// research_window if the runtime block ever carries one, else parse a "m h * * *" cron string,
// else fall back to printing whatever runtime.schedule already says (its normal shape today).
const scheduleSentence = r => {
 const w = r.research_window;
 if (w && w.start) return `daily, ${w.start}${w.end ? `–${w.end}` : ''} Pacific`;
 const cron = /^\s*(\d{1,2})\s+(\d{1,2})\s+\*\s+\*\s+\*\s*$/.exec(r.schedule || '');
 if (cron) return `daily at ${cron[2].padStart(2,'0')}:${cron[1].padStart(2,'0')} Pacific`;
 return r.schedule || 'on a configured schedule';
};
const pacific = d => d ? new Intl.DateTimeFormat('en-CA',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23',timeZone:'America/Los_Angeles',timeZoneName:'short'}).format(new Date(d)) : 'Not yet run';
const sourceLink = id => { const s = sourceOf(id); return `<a class="source-inline" href="${safeUrl(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.publisher)} ↗</a>`; };
const icons = {
 energy:'<path d="m13 2-8 12h6l-1 8 9-13h-7z"/>',
 chips:'<rect x="6" y="6" width="12" height="12" rx="2"/><rect x="9" y="9" width="6" height="6" rx="1"/><path d="M9 2v4m6-4v4M9 18v4m6-4v4M2 9h4m-4 6h4m12-6h4m-4 6h4"/>',
 infrastructure:'<rect x="3" y="3" width="7" height="18" rx="1"/><rect x="14" y="3" width="7" height="18" rx="1"/><path d="M5 7h3m-3 4h3m-3 4h3m8-8h3m-3 4h3m-3 4h3"/>',
 models:'<path d="m12 3 8 5v8l-8 5-8-5V8zM4 8l8 5 8-5m-8 5v8m0-18v10"/>',
 applications:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><path d="M17.5 14v7M14 17.5h7"/>'
};
const icon = id => `<svg class="layer-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[id]}</svg>`;

function chart(metricId, compact=false) {
 const m=metricOf(metricId), companion=m.chart_companion_metric?metricOf(m.chart_companion_metric):null, overlayM=m.chart_overlay_metric?metricOf(m.chart_overlay_metric):null, l=layerOf(m.layer);
 const chartValue=o=>m.unit==='TWh'?valueOf({...o,value:Math.round(o.value),upper:o.upper==null?null:Math.round(o.upper)}):valueOf(o);
 const futureStatus=s=>['forecast','government-target','company-commitment'].includes(s);
 const companionRows=companion?records(companion.id).filter(o=>!overlayM||futureStatus(o.status)):[];
 const overlayRows=overlayM?records(overlayM.id).filter(o=>futureStatus(o.status)):[];
 const all=[...records(metricId),...companionRows,...overlayRows].sort((a,b)=>a.year-b.year||a.period.localeCompare(b.period));
 const chartTitle=m.chart_comparison_title||m.title;
 const showAll=historyWindows.has(metricId),end=Math.max(m.chart_default_end,...all.map(o=>o.year));
 const obs=all.filter(o=>showAll||o.year>=m.chart_default_start);
 const years=[...new Set(obs.map(o=>o.year))].sort((a,b)=>a-b);
 const span=list=>{const values=[...new Set(list)].sort((a,b)=>a-b);return values.length>1?`${values[0]}–${values.at(-1)}`:String(values[0]);};
 const groupVintage=rows=>{const dates=[...new Set(rows.map(o=>sourceOf(o.source).published).filter(Boolean))].sort();return dates.length?(dates.length>1?`${dateLabel(dates[0])}–${dateLabel(dates.at(-1))}`:dateLabel(dates[0])):'date unlisted';};
 const byLabel=new Map();
 obs.forEach(o=>{const label=attributionLabel(o);if(!byLabel.has(label))byLabel.set(label,[]);byLabel.get(label).push(o);});
 const labelOrder=['Reported observation','Historical estimate','Company guidance','Independent projection','Government target','Company commitment'];
 const orderedLabels=[...labelOrder.filter(l=>byLabel.has(l)),...[...byLabel.keys()].filter(l=>!labelOrder.includes(l))];
 const ranges=orderedLabels.map(label=>{const rows=byLabel.get(label);return `${span(rows.map(o=>o.year))} ${label.toLowerCase()}${futureStatus(rows[0].status)?` · published ${groupVintage(rows)}`:''}`;}).join(' · ');
 const historyChrome=`<div class="chart-history">${companion||overlayM?`<p class="scope-warning">${esc(m.chart_comparison_note)}</p>`:''}<p><strong>${esc(ranges||'No catalogued values')}</strong></p><p>Window: ${showAll?m.series_start_year:m.chart_default_start}–${end}. Only published periods are plotted; ${m.chart_type==='line'?'years are evenly spaced':'bar spacing is categorical'}.${m.chart_default_start>2019?` Catalogued series begins ${m.series_start_year}.`:''}</p>${all.some(o=>o.year<m.chart_default_start)?`<label><input class="history-window" type="checkbox" ${showAll?'checked':''}> Show all available history (from ${m.series_start_year})</label>`:''}<p class="${m.definition_stable?'':'methodology-break'}">${m.definition_stable?'':'Methodology break · '}${esc(m.pre_period_note)}</p></div>`;
 if(!obs.length)return `<div class="chart-wrap" data-metric="${esc(metricId)}"><h3>${esc(chartTitle)}</h3><p class="empty">No reviewed observation yet.</p>${historyChrome}<p class="chart-footnote">${esc(m.scope)} Approved sources: ${m.source_ids.map(sourceLink).join(" · ")}</p></div>`;
 const uid=`chart-${metricId}-${++chartSequence}`;
 const narrow=window.innerWidth<600;
 const stepSize = compact ? 70 : 88;
 const widthMin = narrow ? 360 : (compact ? 520 : 640);
 const width = m.chart_type==='line'?(narrow?Math.max(240,window.innerWidth-82):Math.max(960,years.length*45)):Math.max(widthMin, years.length * stepSize + 75), height=m.chart_type==='line'?(narrow?360:340):275, left=narrow?(m.chart_type==='line'?60:44):62, right=m.chart_type==='line'&&narrow?22:65, top=m.chart_type==='line'&&narrow?58:40, bottom=48;
 const ceiling=m.chart_type==='line'?Math.ceil(Math.max(...obs.map(o=>o.value))/250)*250+250:Math.max(...obs.flatMap(o=>[Math.abs(o.value),Math.abs(o.upper??o.value)]),1)*1.2;
 const floor=m.chart_type==='line'?Math.floor((Math.min(...obs.map(o=>o.value))-150)/250)*250:obs.some(o=>o.value<0)?-ceiling:0;
 const plotH=height-top-bottom, plotW=width-left-right;
 const scale=v=>top+plotH-((v-floor)/(ceiling-floor)*plotH);
 let content='';
 for(let i=0;i<=4;i++){const val=floor+(ceiling-floor)*i/4,y=scale(val);content+=`<path d="M${left} ${y}H${width-right}" stroke="#364231" stroke-dasharray="${val?'2 5':'0'}"/><text x="${left-12}" y="${y+4}" text-anchor="end">${number(Math.abs(val)<2?+val.toFixed(2):Math.round(val))}</text>`;}
 content+=`<path class="zero-baseline" d="M${left} ${scale(m.chart_type==='line'?floor:0)}H${width-right}" stroke="#7b8f6d"/>`;
 const step=plotW/Math.max(years.length,1),bw=Math.min(76,step*.45),xOf=year=>left+step*(years.indexOf(year)+.5);
 const pointTitle=o=>`${esc(metricOf(o.metric).title)} · ${esc(o.period)}: ${esc(chartValue(o))} ${esc(m.unit)} · ${attributionLabel(o)}${futureStatus(o.status)?` · published ${vintageLabel(sourceOf(o.source).published)}`:''} · ${esc(sourceOf(o.source).publisher)}`;
 if(m.chart_type==='line'){
  const labeled=new Set([years[0],years.at(-1)]);
  const drawSeries=(rows,color,dash,cls,showLabels)=>{
   const pts=rows.slice().sort((a,b)=>a.year-b.year).map(o=>({o,x:xOf(o.year),y:scale(o.value)}));
   if(!pts.length)return;
   let d='',prev=null;
   pts.forEach(p=>{d+=(prev&&p.o.year===prev.o.year+1?'L':'M')+p.x+' '+p.y;prev=p;});
   content+=`<path class="chart-line ${cls}" d="${d}" fill="none" stroke="${color}" stroke-width="${cls==='overlay-line'?3:2.4}" stroke-linecap="round" stroke-linejoin="round"${dash?` stroke-dasharray="${cls==='overlay-line'?'2 5':'8 5'}"`:''}/>`;
   pts.forEach(p=>{const estimatePoint=p.o.status==='estimate';content+=`<g class="line-point ${cls}${estimatePoint?' estimate-point':''}" data-series="${esc(p.o.metric)}"><title>${pointTitle(p.o)}</title><circle cx="${p.x}" cy="${p.y}" r="${narrow?2.5:4}" fill="${color}" fill-opacity="${estimatePoint?'.45':'1'}" stroke="#101511" stroke-width="1.2"${estimatePoint?' stroke-dasharray="2 1.4"':''}/>${showLabels&&labeled.has(p.o.year)?`<text class="chart-value" x="${p.x}" y="${p.y+(cls==='companion-line'?24:-14)}" text-anchor="${narrow?(p.o.year===years[0]?'start':'end'):'middle'}">${esc(chartValue(p.o))}</text>`:''}</g>`;});
  };
  const primary=obs.filter(o=>o.metric===metricId);
  const reported=primary.filter(o=>!futureStatus(o.status)).sort((a,b)=>a.year-b.year);
  const forecast=primary.filter(o=>futureStatus(o.status)).sort((a,b)=>a.year-b.year);
  drawSeries(reported,l.color,false,'reported-line',true);
  drawSeries(forecast,l.color,true,'forecast-line',true);
  if(reported.length&&forecast.length&&forecast[0].year===reported.at(-1).year+1){
   content+=`<path class="chart-line forecast-line" d="M${xOf(reported.at(-1).year)} ${scale(reported.at(-1).value)}L${xOf(forecast[0].year)} ${scale(forecast[0].value)}" fill="none" stroke="${l.color}" stroke-width="2.4" stroke-dasharray="8 5"/>`;
  }
  if(companion&&forecast.length){
   const next=obs.find(o=>o.metric===companion.id&&o.year===forecast.at(-1).year+1);
   if(next)content+=`<path class="scope-bridge" d="M${xOf(forecast.at(-1).year)} ${scale(forecast.at(-1).value)}L${xOf(next.year)} ${scale(next.value)}" fill="none" stroke="#efc77b" stroke-width="2" stroke-dasharray="2 4"><title>Scope changes: utility-scale to total generation; visual connector only.</title></path>`;
  }
  if(companion)drawSeries(obs.filter(o=>o.metric===companion.id),'#efc77b',true,'companion-line',true);
  if(overlayM)drawSeries(obs.filter(o=>o.metric===overlayM.id),'#78d9ef',true,'overlay-line',true);
  years.filter(year=>!narrow||year%5===0).forEach(year=>{content+=`<text class="chart-year" x="${xOf(year)}" y="${height-23}" text-anchor="middle">${year}</text>`;});
 }else{
  const drawBar=(o,xPos,barW,label)=>{
   const comparison=companion&&o.metric===companion.id, overlayBar=overlayM&&o.metric===overlayM.id;
   const y=scale(o.value),future=futureStatus(o.status),estimateBar=!future&&!overlayBar&&!comparison&&o.status==='estimate';
   const fill=future||overlayBar?`url(#${uid}-${overlayBar||comparison?'comparison':'hatch'})`:estimateBar?`url(#${uid}-estimate)`:(comparison?'#efc77b':l.color);
   return `<g class="bar${overlayBar?' overlay':''}${estimateBar?' estimate-bar':''}" data-series="${esc(o.metric)}"><title>${pointTitle(o)}</title><rect x="${xPos-barW/2}" y="${Math.min(y,scale(0))}" width="${barW}" height="${Math.max(1,Math.abs(scale(0)-y))}" rx="3" fill="${fill}" ${future||overlayBar?`stroke="${overlayBar?'#efc77b':l.color}" stroke-opacity=".75"`:estimateBar?`stroke="${l.color}" stroke-opacity=".55" stroke-dasharray="2 2"`:''}/>${o.upper!=null?`<path d="M${xPos} ${scale(o.upper)}V${y}m-9 0h18m-18 ${scale(o.upper)-y}h18" stroke="${l.color}" stroke-width="2"/>`:''}${label?`<text class="chart-value" x="${xPos}" y="${scale(o.upper??o.value)-12}" text-anchor="middle">${esc(chartValue(o))}</text>`:''}</g>`;
  };
  years.forEach((year,i)=>{
   const items=obs.filter(o=>o.year===year);
   const over=overlayM?items.filter(o=>o.metric===overlayM.id):[];
   const rest=items.filter(o=>!overlayM||o.metric!==overlayM.id);
   const x=left+step*(i+.5);
   over.forEach(o=>{content+=drawBar(o,x,rest.length?bw*1.45:bw,!rest.length);});
   if(rest.length>1) rest.forEach((o,j)=>{const offset=(j-(rest.length-1)/2)*(bw*.9);content+=drawBar(o,x+offset,bw*.72,true);});
   else rest.forEach(o=>{content+=drawBar(o,x,bw,true);});
   const label=rest[0]||over[0];
   content+=`<text x="${x}" y="${height-23}" text-anchor="middle">${esc(label && label.period.length<=(narrow?12:20)?label.period:String(year))}</text>`;
  });
 }
 if(companion){
  const yi=years.findIndex(year=>obs.some(o=>o.year===year&&o.metric===companion.id));
  if(yi>=0){const x=left+step*(yi+.5);content+=`<g class="scope-break-marker"><path d="M${x} ${top-12}V${height-bottom}" stroke="#efc77b" stroke-width="2" stroke-dasharray="5 4"/><text x="${narrow&&m.chart_type==='line'?width-right:x+6}" y="${top-22}" text-anchor="${narrow&&m.chart_type==='line'?'end':'start'}">${narrow&&m.chart_type==='line'?'2028: scope change':esc(m.chart_comparison_label||"Broader AEO scope")+' →'}</text></g>`;}
 }
 if(!m.definition_stable){
  const yi=years.findIndex(year=>year>=m.definition_break_year);
  if(yi>=0){const x=left+step*(yi+.5);content+=`<g class="definition-break-marker"><path d="M${x} ${top-15}V${height-bottom}" stroke="#efc77b" stroke-width="2" stroke-dasharray="5 4"/><text x="${x+6}" y="${top-23}">${m.definition_break_year} method break</text></g>`;}
 }
 const sourceIds=[...new Set(obs.map(o=>o.source))];
 const overlayLegend=overlayM?`<span class="comparison-legend overlay-legend ${m.chart_type==='line'?'line-key high-growth-key':''}">${m.chart_type==='line'?'┈':'▧'} ${esc(m.chart_overlay_legend||'Higher published case')}</span>`:'';
 // Legend text mirrors attributionLabel, but company-authored forecast/commitment share one
 // hatched entry: the point-level distinction lives in pointTitle and the data table.
 const legendBucketOf=o=>{const label=attributionLabel(o);return label==='Reported observation'?'Reported':label==='Historical estimate'?'Estimate':label==='Company guidance'||label==='Company commitment'?'Company guidance / commitment':label==='Independent projection'?'Independent projection':label;};
 const legendPresent=new Set(obs.map(legendBucketOf));
 const legendOrder=[['Reported','legend-swatch'],['Estimate','legend-swatch estimate'],['Company guidance / commitment','legend-swatch forecast'],['Independent projection','legend-swatch forecast']];
 const legendHtml=[...legendOrder.filter(([label])=>legendPresent.has(label)),...[...legendPresent].filter(label=>!legendOrder.some(([l])=>l===label)).map(label=>[label,'legend-swatch forecast'])].map(([label,cls])=>`<span><i class="${cls}"></i>${esc(label)}</span>`).join('');
 return `<div class="chart-wrap" data-metric="${metricId}" data-chart-type="${m.chart_type||'bar'}" data-compact="${compact}" style="--accent:${l.color}"><div class="panel-heading"><div><h3>${esc(chartTitle)}</h3><p>${esc(m.geography)} · ${esc(m.unit)}</p></div><span class="pill">${obs.some(o=>['forecast','company-commitment','government-target'].includes(o.status))?'OUTLOOK':'EVIDENCE'}</span></div>${compact?`<p class="chart-footnote">${esc(ranges)}</p><details class="chart-context"><summary>History & methodology</summary>${historyChrome}</details>`:historyChrome}${m.chart_type==='line'?`<p class="chart-footnote">Axis starts at ${number(floor)} TWh to show change. Dotted bridge at 2028 marks broader coverage, including small on-site generation.</p>`:''}<div class="chart-legend">${legendHtml}${companion?'<span class="comparison-legend baseline-key">'+(m.chart_type==='line'?'┄ ':'▧ ')+esc(m.chart_comparison_legend||'Broader AEO scenario (includes small on-site)')+'</span>':''}${overlayLegend}</div><div class="chart-plot" tabindex="0" role="region" aria-label="${m.chart_type==='line'?'Chart':'Scrollable chart'}: ${esc(m.title)}"><svg class="data-chart" style="min-width:${m.chart_type==='line'?0:(narrow||years.length>8?width:0)}px" viewBox="0 0 ${width} ${height}" role="img" aria-labelledby="${uid}-title ${uid}-desc"><title id="${uid}-title">${esc(m.title)}</title><desc id="${uid}-desc">${obs.map(o=>`${esc(metricOf(o.metric).title)} ${esc(o.period)}: ${esc(chartValue(o))} ${esc(m.unit)}, ${attributionLabel(o)}.`).join(' ')}</desc><defs><pattern id="${uid}-hatch" width="7" height="7" patternUnits="userSpaceOnUse" patternTransform="rotate(35)"><rect width="7" height="7" fill="${l.color}" fill-opacity=".08"/><path d="M0 0v7" stroke="${l.color}" stroke-width="2" stroke-opacity=".6"/></pattern><pattern id="${uid}-comparison" width="7" height="7" patternUnits="userSpaceOnUse" patternTransform="rotate(35)"><rect width="7" height="7" fill="#efc77b" fill-opacity=".08"/><path d="M0 0v7" stroke="#efc77b" stroke-width="2"/></pattern><pattern id="${uid}-estimate" width="6" height="6" patternUnits="userSpaceOnUse"><rect width="6" height="6" fill="${l.color}" fill-opacity=".12"/><circle cx="3" cy="3" r="1.1" fill="${l.color}" fill-opacity=".7"/></pattern></defs>${content}</svg></div><p class="chart-footnote">${esc(m.note)} Sources: ${sourceIds.map(id=>`${sourceLink(id)} — ${esc(sourceOf(id).title)} · ${dateLabel(sourceOf(id).published)}`).join('; ')}.</p><details class="chart-table"><summary>View data & source details</summary><div class="table-scroll"><table><caption class="sr-only">${esc(m.title)} observations and sources</caption><thead><tr><th>Period</th><th>Value (${esc(m.unit)})</th><th>Classification</th><th>Published</th><th>Source / accessed</th></tr></thead><tbody>${obs.map(o=>`<tr><td>${esc(o.period)}</td><td>${esc(chartValue(o))}</td><td>${attributionLabel(o)}${companion||overlayM?`<br>${esc(metricOf(o.metric).title)}`:''}${o.method==='automated'?'<br>Automated extraction':''}</td><td>${vintageLabel(sourceOf(o.source).published)}</td><td>${sourceLink(o.source)}<br>Accessed ${dateLabel(o.retrieved_at)}<br><small>Record: ${esc(o.id)}</small><p>${esc(o.note)}</p></td></tr>`).join('')}</tbody></table></div><p class="chart-footnote">Scope: ${esc(m.scope)}${companion?` Companion: ${esc(companion.scope)}`:''}${overlayM?` Overlay: ${esc(overlayM.scope)}`:''}</p></details></div>`;
}

function sortedEvents(){const replaced=new Set(data.events.map(e=>e.correction_of).filter(Boolean));return data.events.filter(e=>!replaced.has(e.id)).sort((a,b)=>(b.retrieved_at || b.date || '').localeCompare(a.retrieved_at || a.date || ''));}
function noteCorrection(e){
 if(!e.correction_of)return '';
 const old=data.events.find(v=>v.id===e.correction_of);
 return `<p class="chart-footnote">Corrected ${dateLabel(e.corrected_at)}: ${esc(e.correction_reason)}</p><details class="note-history"><summary>Original note and correction history</summary><div id="${esc(old.id)}"><h4>${esc(old.title)}</h4><p>${esc(old.kind)} · Original record</p><p>${esc(old.summary)}</p>${noteCorrection(old)}</div></details>`;
}
function signalRows(items) { return items.length?items.map(e=>{const l=layerOf(e.layer),s=sourceOf(e.source);return `<article id="${esc(e.id)}" class="signal-row" style="--accent:${l.color}"><a class="signal-layer" href="${base}${l.id}/"><i></i>${l.name}</a><div class="signal-body"><h3>${esc(e.title)}${e.correction_of?'<span class="record-badge">Corrected</span>':e.method==='automated'?'<span class="record-badge">Automated</span>':''}</h3><p>${esc(e.summary)}</p>${noteCorrection(e)}</div><div class="signal-meta">${esc(e.kind)}<span>${e.retrieved_at?'Source published':'Dated'}: ${e.date?dateLabel(e.date):'date unlisted'}</span>${e.retrieved_at?`<span>Collected: ${dateLabel(e.retrieved_at)}</span>`:''}<span>${sourceLink(e.source)}</span></div><a href="${safeUrl(s.url)}" target="_blank" rel="noopener noreferrer" aria-label="Read source: ${esc(e.title)}">↗</a></article>`;}).join(''):'<p class="empty">No entries match these filters. Try another layer or search.</p>'; }

function nuclearEnergy(t){
 if(t.id!=='nuclear-goal')return '';
 const rows=records('us-nuclear'),target=rows.find(o=>o.status==='government-target'&&o.year===t.year),baseline=rows.find(o=>o.id==='nuclear-baseline');
 if(!target||!baseline)return '';
 const factor=.9,hours=8760,total=Math.round(target.value*hours*factor/1000),added=Math.round((target.value-baseline.value)*hours*factor/1000);
 return `<div class="nuclear-equivalent"><strong>≈${number(added)} additional TWh / year</strong><p>≈${number(total)} TWh / year total at ${number(target.value)} GW. Illustrative conversion assuming a 90% capacity factor and 8,760 hours per year, relative to the target’s approximate ${number(baseline.value)} GW starting fleet at the same factor.</p><details><summary>How this is calculated</summary><p>Additional annual electricity = (${number(target.value)} − ${number(baseline.value)}) GW × 8,760 hours × 90% ÷ 1,000. This is a conditional capacity-to-energy estimate, not a generation forecast; delivery, retirements and actual utilization determine the outcome.</p></details></div>`;
}

function targetCard(t) {const l=layerOf(t.layer);return `<article class="panel target-card" style="--accent:${l.color}"><div class="target-mini-top"><span class="pill">${esc(t.type)}</span><span class="year">${t.year}</span></div><h3>${esc(t.title)}</h3><p>${esc(t.owner)}</p><div class="target-number">${esc(t.value)}</div>${nuclearEnergy(t)}<span class="assessment">○ ${esc(t.assessment)}</span><p>${esc(t.detail)}</p><p style="margin-top:15px">${sourceLink(t.source)}</p></article>`;}

function codingHome(){
 const total=records('copilot-reviews-cumulative').filter(o=>historicalStatus(o.status)).at(-1);
 return `<article class="panel panel-full coding-evidence" id="coding-agents"><div class="coding-story"><span class="pill">${statusLabel(total.status)}</span><div class="eyebrow muted">SOFTWARE · AGENTS AT WORK</div><h3>AI is becoming part of the code review.</h3><div class="workforce-value">${number(total.value/1000000)} million</div><p><strong>Cumulative Copilot code reviews</strong>, reported by GitHub on ${dateLabel(sourceOf(total.source).published)}.</p><p>An agent examines proposed changes and returns feedback inside the developer’s workflow. This is one measurable slice of AI-assisted software development.</p><p><strong>The opportunity extends beyond coding.</strong> Our outlook is that agents will bring productivity gains to many more digital workflows: research, analysis, design, customer support and business operations. The scale of those gains will depend on reliability, human oversight and measured results in each domain.</p><p class="chart-footnote">Company-reported adoption, not a measured productivity gain. Review counts do not establish accepted fixes, faster delivery or software quality.</p><a class="section-link" href="${base}applications/">Explore software agents & outcomes ↗</a></div><div>${chart('copilot-review-usage-index',true)}</div></article>`;
}

function workforceHome(){
 const cards=[['census-dc-construction-saar','Construction spending','Nominal annualized spending rate; July 2026 preliminary. Includes all private data centers.'],['electrician-openings','Demand for electricians','Projected annual openings, 2025–2035, including replacement needs across all industries.'],['hyperion-construction-jobs','A project built by skilled trades','Expected peak construction jobs at Hyperion. A project commitment, not completed hires.']];
 return `<section class="section" id="building-workforce"><div class="section-top"><div><div class="eyebrow muted">THE PEOPLE BUILDING IT</div><h2>The buildout needs skilled hands.</h2></div><a class="section-link" href="${base}industry/">Explore jobs & local investment ↗</a></div><p class="section-intro">Electricians, construction crews and electrical infrastructure contractors turn investment into working AI factories. Track the spending, demand for workers and project commitments separately.</p><div class="workforce-grid">${cards.map(([id,title,note])=>{const o=records(id).at(-1),m=metricOf(id);return `<article class="panel workforce-card"><span class="pill">${statusLabel(o.status)}</span><h3>${title}</h3><div class="workforce-value">${id==='census-dc-construction-saar'?'$'+number(Math.round(o.value/1000))+'B':valueOf(o)}</div><p>${note}</p><p class="chart-footnote">${esc(o.period)} · ${sourceLink(o.source)}</p></article>`;}).join('')}</div></section>`;
}

function home() {
 const digitLatest=records('digit-gxo-totes').filter(o=>historicalStatus(o.status)).at(-1);
 document.querySelector('#home-details').innerHTML=`<section class="section" id="historical-context"><div class="section-top"><div><div class="eyebrow muted">POWERING THE BUILDOUT</div><h2>More power. A larger productive economy.</h2></div></div><p class="section-intro">Follow U.S. electricity generation through 2035, with the baseline and higher-growth outlook side by side. More generation is the foundation for factories, compute and electrification.</p><div class="history-context-grid"><div class="panel panel-full">${chart('us-utility-generation-history',true)}</div></div><a class="section-link" href="${base}industry/#trades-long-view">Explore the skilled-trades history ↗</a></section>${workforceHome()}<section class="section" id="application-outcomes"><div class="section-top"><div><div class="eyebrow muted">USEFUL INTELLIGENCE</div><h2>From compute to completed work.</h2></div><a class="section-link" href="${base}applications/">Explore applications ↗</a></div><p class="section-intro">Scientific discovery belongs here too. <a class="source-inline" href="${base}applications/#alphafold-medicine">AlphaFold: Nobel-recognized protein prediction and evidence from drug-discovery experiments &#8599;</a></p><div class="history-context-grid">${codingHome()}<div class="panel">${chart('waymo-paid-weekly',true)}<div class="waymo-safety"><h4>Safety alongside adoption</h4><p>IIHS compared driverless Waymo operation with human drivers in the same four cities during 2021–2024.</p><p>Police-reportable crash involvements per million miles: <strong>${valueOf(records('waymo-iihs-police-reportable-crash-rate').at(-1))} for Waymo; ${valueOf(records('human-iihs-matched-crash-rate').at(-1))} for matched human driving.</strong> The study covers about 50 million driverless miles. ${sourceLink('iihs-waymo-crash-2026')}</p></div></div><aside class="panel outcome-editorial"><span class="pill">${statusLabel(digitLatest.status)}</span><div class="eyebrow muted">ROBOTS AT WORK</div><h3>Warehouse work, already happening.</h3><div class="workforce-value">${valueOf(digitLatest)}</div><p><strong>Totes handled by Digit at GXO.</strong> A cumulative company-reported milestone at one logistics site, showing a humanoid robot performing a repeatable commercial task.</p><p>Completed handling is evidence of deployed work. It does not establish fleet-wide productivity or hours of labor saved.</p><p class="chart-footnote">${dateLabel(digitLatest.retrieved_at)} review · ${sourceLink(digitLatest.source)}</p><a class="section-link" href="${base}applications/">Explore productive robotics ↗</a></aside></div></section><section class="section" id="outlook"><div class="section-top"><div><div class="eyebrow muted">THE LONG VIEW</div><h2>The road to 2030. And beyond.</h2></div><span class="section-aside">Observed progress. Attributed ambitions.</span></div><p class="section-intro">The 2030 bar is the IEA 2026 data-center outlook. The 2035 bar is the IEA 2025 Lift-Off case, the higher published sensitivity, not an update of 2030 and not a probability interval.</p><div class="outlook-grid"><div class="panel">${chart('dc-electricity',true)}</div><aside class="panel"><div class="eyebrow muted">THREE SEPARATE TARGET BOOKS</div><h3 style="margin-top:12px">Targets, commitments, projections.</h3><p class="target-intro">Government targets, company commitments and independent projections stay separate. They are never blended into a single goal.</p>${[...data.targets].sort((a,b)=>['Government target','Company commitment','Independent forecast'].indexOf(a.type)-['Government target','Company commitment','Independent forecast'].indexOf(a.type)).map(t=>`<article class="target-mini" aria-label="${esc(t.type)} book"><div class="target-mini-top"><span class="pill">${esc(t.type)}</span><span class="year">${t.year} ↗</span></div><h4>${esc(t.title)}</h4><div class="target-number">${esc(t.value)}</div>${nuclearEnergy(t)}<p>${esc(t.assessment)} · ${sourceLink(t.source)}</p></article>`).join('')}</aside></div></section>${industrialPremise()}<section class="manifesto"><div><h2>Optimism, with the receipts.</h2><p>Every number has a source, every projection is labeled, and every update leaves a trail. Delays, costs, missing evidence and corrections stay in view.</p></div><a href="${base}methodology/">How we research ↗</a></section>`;
}

function layerPage(id) {
 const preservedDiagram=document.querySelector('#layer-diagram');
 const l=layerOf(id), ms=data.metrics.filter(m=>m.layer===id&&!m.id.startsWith('revenue-')).sort((a,b)=>Number(b.id===l.headline_metric)-Number(a.id===l.headline_metric)), targets=data.targets.filter(t=>t.layer===id);
 root.innerHTML=`<section class="page-hero" style="--accent:${l.color}"><div class="breadcrumb"><a href="${base}">Overview</a><span>/</span><span>${l.name}</span></div><div class="eyebrow">LAYER ${l.number} / ${l.name}</div><h1>${l.tagline}</h1><p>${l.description}</p></section><nav class="layer-nav" aria-label="Explore layers">${data.layers.map(v=>`<a href="${base}${v.id}/" class="${v.id===id?'active':''}" style="--accent:${v.color}" ${v.id===id?'aria-current="page"':''}>${v.number} &nbsp; ${v.name}</a>`).join('')}</nav><div class="detail-layout"><section class="panel"><label class="eyebrow muted" for="metric-select">TRACKED INDICATOR</label><select class="select-control" id="metric-select">${ms.map(m=>`<option value="${m.id}">${esc(m.title)}</option>`).join('')}</select><div id="metric-chart" style="margin-top:24px">${chart(ms[0].id)}</div></section><aside class="panel" style="--accent:${l.color}"><div class="eyebrow muted">WHAT WE’RE WATCHING</div><h3 style="margin-top:15px">The next steps forward.</h3><ul class="research-focus">${l.focus.map(f=>`<li>${esc(f)}</li>`).join('')}</ul><p class="target-intro">${esc(l.outlook)}</p><div class="connection" style="margin-top:26px"><strong>Connected to the stack</strong>${esc(l.connection)}</div></aside></div>${layerPurpose(id)}<section class="section"><div class="section-top"><div><div class="eyebrow muted">GOALS & OUTLOOK</div><h2>What are we building toward?</h2></div></div>${targets.length?`<div class="target-grid">${targets.map(targetCard).join('')}</div>`:`<div class="panel"><h3>Progress has more than one measure.</h3><p class="target-intro">There is no single verified ${l.name.toLowerCase()} buildout target in this initial ledger. We track ${esc(l.focus.map(x=>x.toLowerCase()).join(', '))}. Attributed targets will be added as comparable evidence becomes available.</p><p class="chart-footnote">A missing target is a research gap, not evidence of missing progress.</p></div>`}</section><section class="section"><div class="section-top"><h2>Inside the ${l.name.toLowerCase()} layer.</h2><a class="section-link" href="${base}ledger/?layer=${l.id}">Open layer ledger ↗</a></div><div class="signal-list">${signalRows(sortedEvents().filter(e=>e.layer===id))}</div></section>`;
 if(preservedDiagram)root.querySelector('.page-hero').after(preservedDiagram);
 document.querySelector('#metric-select').addEventListener('change',e=>document.querySelector('#metric-chart').innerHTML=chart(e.target.value));
}

function ledger() {
 root.innerHTML=`<section class="page-hero"><div class="eyebrow">THE OPEN RESEARCH FEED</div><h1>A record of real progress.</h1><p>Explore the evidence, inspect the numbers, and follow the daily research. Original reporting dates stay attached to every finding.</p></section><div class="ledger-toolbar"><p>${data.observations.filter(o=>!o.superseded_by).length} observations · ${data.sources.length} registered sources · ${data.layers.length} connected layers</p><div style="display:flex;gap:10px"><button class="button outline" id="download-csv">Download CSV ↓</button><a class="button outline" href="${base}data/ledger.json" download="stack-ledger.json">Raw JSON ↓</a></div></div><label for="research-search" class="sr-only">Search research</label><input class="search" id="research-search" type="search" placeholder="Search the ledger: nuclear, inference, adoption…"><div class="filters" role="group" aria-label="Filter by layer"><button class="filter active" data-layer="all" aria-pressed="true">All layers</button>${data.layers.map(l=>`<button class="filter" data-layer="${l.id}" aria-pressed="false">${l.name}</button>`).join('')}</div><p id="result-count" class="chart-footnote" aria-live="polite"></p><h2 class="subheading">Research notes</h2><div id="research-results"></div><h2 class="subheading">The numbers behind the story</h2><div id="record-results"></div><section class="section" style="margin-top:40px"><div class="section-top"><div><div class="eyebrow muted">DAILY OPERATIONS</div><h2>Research run history.</h2></div></div>${runHistory()}</section>`;
 let selected=new URLSearchParams(location.search).get('layer') || 'all';
 if(!data.layers.some(l=>l.id===selected))selected='all';
 function update(){const q=document.querySelector('#research-search').value.toLowerCase().trim();const events=sortedEvents().filter(e=>(selected==='all'||e.layer===selected)&&`${e.title} ${e.summary} ${sourceOf(e.source).publisher}`.toLowerCase().includes(q));const obs=data.observations.filter(o=>!o.superseded_by&&(selected==='all'||metricOf(o.metric).layer===selected)&&`${metricOf(o.metric).title} ${o.period} ${o.note} ${sourceOf(o.source).publisher}`.toLowerCase().includes(q)).sort((a,b)=>b.year-a.year);document.querySelector('#research-results').innerHTML=signalRows(events);document.querySelector('#record-results').innerHTML=obs.length?obs.map(o=>{const m=metricOf(o.metric),l=layerOf(m.layer);return `<article id="${esc(o.id)}" class="record-row" style="--accent:${l.color}"><a class="signal-layer" href="${base}${l.id}/"><i></i>${l.name}</a><div><h3><a href="${base}${l.id}/">${esc(m.title)} ↗</a>${o.method==='automated'?'<span class="record-badge">Automated</span>':''}</h3><p>${esc(o.period)} · ${attributionLabel(o)} · ${esc(m.geography)}</p><p>${sourceLink(o.source)} · Accessed ${dateLabel(o.retrieved_at)}</p>${o.note?`<p>${esc(o.note)}</p>`:''}<p>Record ${esc(o.id)}</p></div><div class="record-value">${esc(valueOf(o))}<small>${esc(m.unit)}</small></div></article>`;}).join(''):'<p class="empty">No matching observations.</p>';document.querySelector('#result-count').textContent=`${events.length} research notes and ${obs.length} observations`;document.querySelectorAll('[data-layer]').forEach(b=>{b.classList.toggle('active',b.dataset.layer===selected);b.setAttribute('aria-pressed',String(b.dataset.layer===selected));});}
 document.querySelectorAll('[data-layer]').forEach(b=>b.addEventListener('click',()=>{selected=b.dataset.layer;history.replaceState(null,'',`${location.pathname}${selected==='all'?'':`?layer=${selected}`}`);update();}));
 document.querySelector('#research-search').addEventListener('input',update);
 document.querySelector('#download-csv').addEventListener('click',downloadCsv); update();
}
function runHistory(){return data.runs.length?`<div class="table-scroll"><table class="run-table"><thead><tr><th>Run (Pacific)</th><th>Status</th><th>Documents</th><th>New records</th><th>Quarantined</th><th>Source failures</th></tr></thead><tbody>${[...data.runs].reverse().slice(0,30).map(r=>`<tr><td>${esc(pacific(r.finished_at))}</td><td>${esc(r.status)}</td><td>${r.documents_fetched}</td><td>${r.accepted}</td><td>${r.quarantined}</td><td>${r.source_failures.length?esc(r.source_failures.map(f=>f.source+': '+f.reason).join('; ')):'None'}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">The initial research was curated during setup. The first local-model run has not completed yet.</div>';}
function downloadCsv(){const cols=['id','layer','metric','geography','period','year','value','upper','unit','precision','status','source_url','retrieved_at','method','metric_id','company','measurement_type','project','scope','source_published'];const rows=data.observations.filter(o=>!o.superseded_by).map(o=>{const m=metricOf(o.metric);return [o.id,m.layer,m.title,m.geography,o.period,o.year,o.value,o.upper,m.unit,o.precision,o.status,sourceOf(o.source).url,o.retrieved_at,o.method,m.id,m.company||"",m.measurement_type||"",m.project||"",m.scope,sourceOf(o.source).published||""];});const quote=v=>{let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};const blob=new Blob(['\uFEFF'+[cols,...rows].map(r=>r.map(quote).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'});const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='stack-ledger-observations.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}

function methodology(){root.innerHTML=`<section class="page-hero"><div class="eyebrow">OPTIMISM, WITH THE RECEIPTS</div><h1>Open by design.<br>Grounded in evidence.</h1><p>How Stack Ledger researches, measures and publishes the AI buildout. A clear trail from the chart to the original source.</p></section><div class="prose-grid"><nav class="prose-nav" aria-label="Methodology contents"><a href="#principles">Research principles</a><a href="#premise-evidence">Testing our premise</a><a href="#reading">Reading the data</a><a href="#automation">Daily research</a><a href="#sources">Source library</a><a href="#corrections">Corrections & reuse</a></nav><div class="prose"><h2 id="principles">A constructive view of progress.</h2><p>We follow energy, chips, infrastructure, models and applications as one connected system. Our perspective is global, with deeper U.S. tracking, a 2030 outlook and room for longer horizons.</p><p><strong>Positive in tone. Faithful to the evidence.</strong> We highlight demonstrated advances and explain what can unlock the next ones. Delays, uncertainty and local impacts remain part of the record. Source coverage is a starting collection, not a comprehensive census.</p><p>The five-layer concept comes from <a class="source-inline" href="https://blogs.nvidia.com/blog/ai-5-layer-cake/">Jensen Huang’s framework ↗</a>. Stack Ledger is an independent project, unaffiliated with NVIDIA.</p><h2 id="premise-evidence">A vision for reindustrialization. Evidence for each step.</h2><p>Our guiding ambition is to help make the case for building: more power, stronger domestic manufacturing, productive AI factories, and useful digital and physical work. We examine whether this buildout is delivering lasting value to American communities, with global context and horizons beyond 2030.</p><p>Follow investment into delivered capacity, local supplier purchases, wages and operating jobs. Follow compute into reliable models and agent systems, then into completed business tasks, productive robots and scientific or medical outcomes. Each link needs its own evidence; spending alone cannot establish the whole chain.</p><p>We distinguish robot demonstrations from operating deployments, and drug candidates from clinical results or patient benefits. We track reliability, human intervention, costs and practical outcomes. Community benefits need local evidence, alongside electricity affordability, public costs and other impacts.</p><p>These are research priorities, not guaranteed outcomes. The daily researcher receives this purpose through its constitution and works within approved sources and metrics. Missing coverage remains a visible research gap.</p><h2 id="reading">Different kinds of evidence, clearly labeled.</h2><div class="legend-grid"><div><strong>Reported observation</strong><p>A historical measurement or directly reported result. Company-reported figures retain their attribution.</p></div><div><strong>Historical estimate</strong><p>A modeled or approximate historical quantity, rather than a directly measured total.</p></div><div><strong>Forecast</strong><p>A source’s projection of a future outcome. It is a planning reference, not a promise.</p></div><div><strong>Target or commitment</strong><p>An attributed ambition with an owner and horizon. Announced spending is not delivered capacity.</p></div></div><p>Charts use zero-based bars and preserve the reported periods. Hatched bars identify forecasts and commitments. Missing years are not filled with invented data. Each metric has its own reviewed history start and visible window, normally beginning in 2019 when comparable data exists. Published forecasts beyond 2030 extend the window automatically. Earlier reviewed history is available through the chart control. Methodology breaks and source vintages remain visible; separate scenario cases are never averaged. Each chart has an accessible data table, source links, units and scope.</p><p>GW measures power; TWh measures energy. Data-center totals include workloads beyond AI. A facility count is not installed compute. Survey adoption is not measured productivity. These distinctions stay attached to the data.</p><p>We do not publish an overall AI completion percentage. A target can be assessed only against compatible observations and a defensible trajectory. If that evidence is missing, the site says so. A newly retrieved old report is not a new milestone.</p><h2 id="automation">Local intelligence. A traceable daily process.</h2><p>The configured research model is <strong>${esc(data.runtime.display_model)}</strong>, served through Ollama on the owner’s home PC. OpenClaw runs a controlled script on this schedule: ${esc(scheduleSentence(data.runtime))}. The machine, Ollama and OpenClaw gateway must be running.</p><ol><li>Fetch approved public sources and a bounded set of relevant same-host links. Respect robots.txt, request limits and inaccessible pages.</li><li>Ask the local model for structured numeric observations within the reviewed metric catalog, and concise research notes from newly discovered articles.</li><li>Check that supporting text exists in the fetched document, numeric tokens match, and units, dates, classifications and scope agree. A separate model pass screens the complete claim.</li><li>Quarantine conflicts and unsupported proposals. Validate the data and generated site, then commit and push accepted updates.</li></ol><p><strong>Automated screening is fallible.</strong> Two passes of the same model are not independent fact-checking. Machine-added records are labeled, and sources remain available for inspection. The unattended agent cannot change code, templates, metrics, source policy or its constitution. New metrics and corrections require review.</p><p>Private discovery reserves part of the same run budget for broad questions and unfamiliar public sources. It retains evidence and proposes coverage additions for human review; it cannot register public sources, change metrics or select homepage content. Monitoring, discovery, editorial review and publication have distinct receipts and permissions.</p><p>A run may legitimately find no new records. Run history reports retrieved documents, accepted observations, quarantined proposals and source failures. Last attempt and last successful research are separate timestamps.</p><p><a class="source-inline" href="https://github.com/reedos/stack_ledger/blob/main/research/CONSTITUTION.md">Read the full research constitution ↗</a></p><h2 id="sources">The source library.</h2><p>Primary sources come first: public agencies, original research, technical reports and direct project disclosures. Company claims are attributed to their issuer. An unknown publication date remains unknown.</p>${data.sources.map(s=>`<article class="source-card"><a href="${safeUrl(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a><p>${esc(s.publisher)} · ${dateLabel(s.published)} · ${esc(s.license)}</p></article>`).join('')}<h2 id="corrections">A ledger that can be corrected.</h2><p>Found an issue? <a class="source-inline" href="https://github.com/reedos/stack_ledger/issues">Open a correction request ↗</a> with the record ID, original source and supporting evidence. Reviewed corrections preserve the original record and link to its replacement. Conflicting automated findings are held for review.</p><p>Download the structured dataset from <a class="source-inline" href="${base}ledger/">the ledger</a>. Original code is MIT licensed. Source facts retain their attribution and underlying source materials retain their original rights. IEA-derived material is attributed under its stated CC BY 4.0 terms where applicable.</p></div></div>`;}

function sessionSummary(s){
 if(!s)return '<li>Latest research session: no published session summary yet.</li>';
 const n=v=>v.toLocaleString('en-US');
 const missing=s.receipts_recorded!==s.batches?` Recorded totals from ${n(s.receipts_recorded)} of ${n(s.batches)} batch receipts; missing receipts are not zero activity.`:'';
 return `<li>Latest research session: ${esc(s.state)} · started ${esc(pacific(s.started_at))} · ${n(Math.floor(s.elapsed_seconds/60))} minutes elapsed · ${n(s.batches)} batches (${n(s.failed_batches)} failed). ${n(s.documents_fetched)} document fetches (includes repeats), ${n(s.model_calls)} model calls, ${n(s.accepted)} accepted monitoring records, ${n(s.quarantined)} quarantined proposals; ${n(s.source_failures)} source failures and ${n(s.discovery_errors)} discovery errors. Elapsed time includes waits and publication checks.${missing}</li>`;
}
function runtime(){const r=data.runtime;document.querySelector('#runtime').innerHTML=`<strong>Research runtime:</strong> ${esc(r.display_model)} · ${esc(r.engine)} · ${esc(r.hardware)}<br><strong>Last run:</strong> ${esc(pacific(r.last_attempt))} · <strong>Status:</strong> ${esc(r.status)} · <strong>Last successful research:</strong> ${esc(pacific(r.last_success))}<details><summary>Runtime details & provenance</summary><ul><li>Exact model: ${esc(r.model)}</li><li>Schedule: ${esc(r.schedule)}. Hardware configuration is owner-reported.</li><li>Initial curated dataset: ${esc(data.seed_date)}. Automated records are labeled individually.</li>${sessionSummary(r.latest_session)}</ul></details>`;}

// Native disclosure navigation also works before the datasets load.
const stackMenu=document.querySelector('.stack-menu');
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&stackMenu.open){stackMenu.open=false;stackMenu.querySelector('summary').focus();}});
document.addEventListener('click',event=>{if(!stackMenu.contains(event.target))stackMenu.open=false;});

Promise.all(['ledger','ecosystem','delivery','fabric','expansion','agenda','source-books','excerpts'].map(name=>fetch(`${base}data/${name}.json?v=${encodeURIComponent(document.body.dataset.build||'')}`).then(r=>{if(!r.ok)throw new Error(`Dataset request returned ${r.status}`);return r.json();}))).then(([d,e,t,f,x,a,b,q])=>{data=d;ecosystem=e;delivery=t;fabric=f;expansion=x;if(page==='home')home();else if(page==='ledger')ledger();else if(page==='methodology')methodology();else if(page==='projects')projectsPage();else if(page==='companies')companiesPage();else if(page==='company')companyPage();else if(page==='industry')industryPage();else if(page==='claims'){/* Complete reviewed snapshot is rendered at build time. */}else if(layerOf(page))layerPage(page);else throw new Error('Unknown page');extendWithEcosystem();extendWithDelivery();extendWithFabric();extendWithExpansion();extendWithAgenda(a,b,q);enhanceExplorers();runtime();document.body.dataset.enhanced="true";document.querySelector(`[data-nav="${page==='home'||layerOf(page)?'stack':page==='company'?'companies':page}"]`)?.classList.add('active');if(location.hash)requestAnimationFrame(()=>document.getElementById(location.hash.slice(1))?.scrollIntoView());}).catch(err=>{root.insertAdjacentHTML('beforeend','<p id="load-status" class="empty" role="status"></p>');document.querySelector('#load-status').textContent='Interactive research could not be loaded. The built snapshot remains available; use the raw dataset or repository for the full record.';console.error(err);});

let narrowCharts=window.innerWidth<600;
window.addEventListener('resize',()=>{const next=window.innerWidth<600;if(data&&next!==narrowCharts){narrowCharts=next;document.querySelectorAll('.chart-wrap').forEach(el=>{el.outerHTML=chart(el.dataset.metric);});}});
